from pathlib import Path

p = Path("src/components/TracksPlayer.jsx")
s = p.read_text()

# Remove any temporary test text.
s = s.replace('<div className="nyxtryp-auto-test">ПРИВЕТ</div>', '')
s = s.replace('ПРИВЕТ', '')

# Replace the existing VU markup with the SVG-based geometry from reference #3.
start_marker = '          {!isMobile && (\n            <div className="tracks-mc-vu">'
end_marker = '          <div className="tracks-controls">'
start = s.find(start_marker)
end = s.find(end_marker, start)
if start < 0 or end < 0:
    raise SystemExit("VU markup boundaries not found")

new_block = '''          {!isMobile && (\n            <div className="tracks-mc-vu">\n              {[['L', leftVU], ['R', rightVU]].map(([channel, value]) => {\n                const normalized = Math.max(0, Math.min(1, (value + 40) / 50))\n                const angle = -42 + normalized * 84\n                const ticks = Array.from({ length: 11 }, (_, i) => {\n                  const t = i / 10\n                  const x = 34 + 292 * t\n                  const y = 116 - 40 * (4 * t * (1 - t))\n                  const dx = 292\n                  const dy = -160 * (t - 0.5)\n                  const len = Math.hypot(dx, dy)\n                  return { i, x, y, nx: -dy / len, ny: dx / len }\n                })\n                const labels = ['-40', '-30', '-20', '-10', '0', '+10']\n                return (\n                  <div className="tracks-mc-meter" key={channel}>\n                    <div className="tracks-mc-window">\n                      <svg className="tracks-mc-gauge" viewBox="0 0 360 150" preserveAspectRatio="xMidYMid meet" aria-label={`${channel} analog VU meter`}>\n                        <defs>\n                          <linearGradient id={`mc-bg-${channel}`} x1="0" y1="0" x2="0" y2="1">\n                            <stop offset="0" stopColor="#b9edf8" />\n                            <stop offset="0.55" stopColor="#5abddc" />\n                            <stop offset="1" stopColor="#207da3" />\n                          </linearGradient>\n                          <radialGradient id={`mc-light-${channel}`} cx="50%" cy="55%" r="75%">\n                            <stop offset="0" stopColor="#ffffff" stopOpacity=".28" />\n                            <stop offset="0.65" stopColor="#dff8ff" stopOpacity=".05" />\n                            <stop offset="1" stopColor="#00151e" stopOpacity="0" />\n                          </radialGradient>\n                          <filter id={`mc-needle-glow-${channel}`} x="-50%" y="-50%" width="200%" height="200%">\n                            <feGaussianBlur stdDeviation="1.5" />\n                          </filter>\n                        </defs>\n                        <rect x="1" y="1" width="358" height="148" rx="3" fill="#02080c" stroke="#40515a" strokeWidth="2" />\n                        <rect x="7" y="7" width="346" height="136" rx="2" fill={`url(#mc-bg-${channel})`} />\n                        <rect x="7" y="7" width="346" height="136" rx="2" fill={`url(#mc-light-${channel})`} />\n                        <path d="M34 116 Q180 76 326 116" fill="none" stroke="rgba(3,30,44,.96)" strokeWidth="2" />\n                        {ticks.map(tick => {\n                          const major = tick.i % 2 === 0\n                          const inner = major ? 6 : 4\n                          const outer = major ? 17 : 11\n                          return (\n                            <g key={tick.i}>\n                              <line x1={tick.x + tick.nx * inner} y1={tick.y + tick.ny * inner} x2={tick.x + tick.nx * outer} y2={tick.y + tick.ny * outer} stroke="rgba(3,28,43,.96)" strokeWidth={major ? 1.5 : 1} />\n                              {major && (\n                                <text x={tick.x + tick.nx * 27} y={tick.y + tick.ny * 27 + 3} textAnchor="middle" fill="rgba(2,29,44,.96)" fontSize="8" fontFamily="Arial, sans-serif">{labels[tick.i / 2]}</text>\n                              )}\n                            </g>\n                          )\n                        })}\n                        <text x="180" y="30" textAnchor="middle" fill="rgba(2,28,43,.96)" fontSize="9" fontWeight="700" fontFamily="Arial, sans-serif" letterSpacing="2.2">McINTOSH</text>\n                        <text x="180" y="41" textAnchor="middle" fill="rgba(2,28,43,.85)" fontSize="6.5" fontFamily="Arial, sans-serif" letterSpacing="1.1">STEREO POWER OUTPUT</text>\n                        <text x="180" y="137" textAnchor="middle" fill="rgba(2,28,43,.8)" fontSize="7" fontFamily="Arial, sans-serif" letterSpacing="1.4">{channel}</text>\n                        <line x1="180" y1="116" x2="180" y2="48" stroke="rgba(255,255,255,.38)" strokeWidth="4" strokeLinecap="round" filter={`url(#mc-needle-glow-${channel})`} />\n                        <g transform={`rotate(${angle} 180 116)`}>\n                          <line x1="180" y1="116" x2="180" y2="48" stroke="#f8fcff" strokeWidth="2.2" strokeLinecap="round" />\n                          <line x1="180" y1="116" x2="180" y2="54" stroke="#21465b" strokeWidth="0.8" strokeLinecap="round" />\n                        </g>\n                        <circle cx="180" cy="116" r="5" fill="#e2eef3" stroke="#173b4e" strokeWidth="1.5" />\n                        <circle cx="180" cy="116" r="1.5" fill="#07151c" />\n                      </svg>\n                    </div>\n                  </div>\n                )\n              })}\n            </div>\n          )}\n\n'''
s = s[:start] + new_block + s[end:]

# Replace the meter-specific CSS so it matches the new SVG proportions.
css_start = s.find('        .tracks-mc-vu {')
css_end = s.find('        @media (max-width: 600px) {', css_start)
if css_start < 0 or css_end < 0:
    raise SystemExit("VU CSS boundaries not found")

new_css = '''        .tracks-mc-vu {\n          display: flex;\n          width: 100%;\n          gap: 14px;\n          justify-content: center;\n          align-items: stretch;\n          padding: 2px 0 4px;\n        }\n\n        .tracks-mc-meter {\n          flex: 1 1 0;\n          min-width: 0;\n        }\n\n        .tracks-mc-window {\n          width: 100%;\n          overflow: hidden;\n          border-radius: 3px;\n          background: #02080c;\n          border: 1px solid rgba(190,214,228,.42);\n          box-shadow: inset 0 0 0 1px rgba(0,0,0,.95), 0 5px 15px rgba(0,0,0,.28);\n        }\n\n        .tracks-mc-gauge {\n          width: 100%;\n          height: auto;\n          display: block;\n          aspect-ratio: 360 / 150;\n        }\n\n'''
s = s[:css_start] + new_css + s[css_end:]
p.write_text(s)
print("NYXTRYP: installed reference #3 SVG VU geometry")
